    double total = 0.0;
    double v[3];
    double r[3];
    double t[3];
    double c[3];
    double p[3];
    double nt[3];
    int i;

    if ((temperature == NULL) || (voltage == NULL) || (resistance == NULL) ||
        (next_temperature == NULL) || (current == NULL) || (power == NULL) ||
        (total_power == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(temperature->x)) || (!isfinite(temperature->y)) || (!isfinite(temperature->z)) ||
        (!isfinite(voltage->x)) || (!isfinite(voltage->y)) || (!isfinite(voltage->z)) ||
        (!isfinite(resistance->x)) || (!isfinite(resistance->y)) || (!isfinite(resistance->z)) ||
        (!isfinite(ambient)) || (!isfinite(thermal_capacity)) || (!isfinite(thermal_resistance)) ||
        (!isfinite(dt))) {
        return ADCS_E_RANGE;
    }
    if ((resistance->x <= 0.0) || (resistance->y <= 0.0) || (resistance->z <= 0.0) ||
        (thermal_capacity <= 0.0) || (thermal_resistance <= 0.0) || (dt < 0.0)) {
        return ADCS_E_RANGE;
    }

    v[0] = voltage->x;
    v[1] = voltage->y;
    v[2] = voltage->z;
    r[0] = resistance->x;
    r[1] = resistance->y;
    r[2] = resistance->z;
    t[0] = temperature->x;
    t[1] = temperature->y;
    t[2] = temperature->z;

    for (i = 0; i < 3; i++) {
        c[i] = v[i] / r[i];
        p[i] = (v[i] * v[i]) / r[i];
        total += p[i];
    }

    current->x = c[0];
    current->y = c[1];
    current->z = c[2];
    power->x = p[0];
    power->y = p[1];
    power->z = p[2];

    for (i = 0; i < 3; i++) {
        nt[i] = t[i] + dt * (p[i] - (t[i] - ambient) / thermal_resistance) / thermal_capacity;
    }
    next_temperature->x = nt[0];
    next_temperature->y = nt[1];
    next_temperature->z = nt[2];

    *total_power = total;

    return ADCS_OK;
}

